    transition: color 0.3s ease;
}

a:hover {
    color: var(--accent-light);
}

button {
    font-family: inherit;
    cursor: pointer;
    border: none;
    transition: all 0.3s ease;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

/* ============================
   Layout
   ============================ */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

.section {
    padding: 80px 0;
}

.section-header {
    text-align: center;
    margin-bottom: 60px;
}

.section-header h2 {
    font-size: 2.5rem;
    margin-bottom: 10px;
    font-weight: 700;
    letter-spacing: -1px;
}

.section-header p {
    font-size: 1.1rem;
    color: var(--text-secondary);
}

/* ============================
   Header & Navigation
   ============================ */
