   ============================ */
class MobileNav {
    constructor() {
        this.init();
    }

    init() {
        const nav = document.querySelector('.nav');
        if (!nav) return;

        if (window.innerWidth < 768) {
            nav.setAttribute('role', 'navigation');
        }

        window.addEventListener('resize', () => {
            if (window.innerWidth < 768) {
                nav.setAttribute('role', 'navigation');
            }
        });
    }
}

/* ============================
