    --shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
}

/* ============================
   Reset & Base
   ============================ */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background-color: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.6;
}

a {
    color: var(--accent);
    text-decoration: none;
    transition: color 0.3s ease;
}

a:hover {
    color: var(--accent-light);
}

button {
    font-family: inherit;
    cursor: pointer;
    border: none;
    transition: all 0.3s ease;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

/* ============================
   Layout
   ============================ */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

.section {
    padding: 80px 0;
}

.section-header {
    text-align: center;
    margin-bottom: 60px;
}

.section-header h2 {
    font-size: 2.5rem;
    margin-bottom: 10px;
    font-weight: 700;
    letter-spacing: -1px;
}

.section-header p {
    font-size: 1.1rem;
    color: var(--text-secondary);
}

/* ============================
   Header & Navigation
   ============================ */
.header {
    background-color: var(--bg-secondary);
    border-bottom: 1px solid var(--border);
    padding: 20px 0;
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 40px;
}

.logo h1 {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 2px;
    background: linear-gradient(135deg, var(--accent), var(--accent-light));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.nav {
    display: flex;
    gap: 40px;
    flex: 1;
    justify-content: center;
}

.nav-link {
    font-size: 0.95rem;
    color: var(--text-primary);
    transition: color 0.3s ease;
}

.nav-link:hover {
    color: var(--accent);
}

.header-actions {
    display: flex;
    gap: 20px;
}

.icon-btn {
    background: none;
    color: var(--text-primary);
    padding: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.icon-btn:hover {
    color: var(--accent);
}

/* ============================
   Hero Section
   ============================ */
.hero {
    background: linear-gradient(135deg, var(--bg-secondary) 0%, var(--bg-tertiary) 100%);
    padding: 120px 20px;
    text-align: center;
    border-bottom: 1px solid var(--border);
}

.hero-content {
    max-width: 600px;
    margin: 0 auto;
}

.hero-content h2 {
    font-size: 3.5rem;
    margin-bottom: 20px;
    font-weight: 700;
    letter-spacing: -1px;
    background: linear-gradient(135deg, var(--accent), var(--text-primary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.hero-content p {
    font-size: 1.3rem;
    color: var(--text-secondary);
    margin-bottom: 40px;
}

.cta-btn {
    display: inline-block;
    background-color: var(--accent);
    color: var(--bg-primary);
    padding: 14px 40px;
    border-radius: 50px;
    font-weight: 600;
    font-size: 1rem;
    transition: all 0.3s ease;
    box-shadow: 0 4px 15px rgba(212, 175, 55, 0.2);
}

.cta-btn:hover {
    background-color: var(--accent-light);
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(212, 175, 55, 0.3);
}

/* ============================
   Products Grid
   ============================ */
.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 40px;
    margin-bottom: 40px;
}

.product-card {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 12px;
    overflow: hidden;
    transition: all 0.3s ease;
}

.product-card:hover {
    border-color: var(--accent);
    box-shadow: var(--shadow);
    transform: translateY(-8px);
}

.product-image {
    width: 100%;
    height: 250px;
    background-color: var(--bg-tertiary);
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info {
    padding: 24px;
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 8px;
    color: var(--text-primary);
}

.product-desc {
    font-size: 0.9rem;
    color: var(--text-secondary);
    margin-bottom: 16px;
}

.product-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 16px;
    font-size: 0.95rem;
}

.price {
    font-weight: 700;
    font-size: 1.2rem;
    color: var(--accent);
}

.rating {
    color: var(--accent);
    letter-spacing: 2px;
}

.add-to-cart-btn {
    width: 100%;
    background-color: var(--bg-tertiary);
    color: var(--accent);
    padding: 12px;
    border: 1px solid var(--accent);
    border-radius: 6px;
    font-weight: 600;
    font-size: 0.9rem;
    transition: all 0.3s ease;
}

.add-to-cart-btn:hover {
    background-color: var(--accent);
    color: var(--bg-primary);
}

/* ============================
   Deals Section
   ============================ */
.deals-section {
    background-color: var(--bg-secondary);
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 30px;
}

.deal-card {
    background: linear-gradient(135deg, var(--bg-tertiary), rgba(212, 175, 55, 0.05));
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 40px;
    position: relative;
    transition: all 0.3s ease;
    cursor: pointer;
}

.deal-card:hover {
    border-color: var(--accent);
    transform: translateY(-4px);
}

.deal-card.large-deal {
    grid-column: span 1;
    padding: 60px 40px;
}

.deal-badge {
    position: absolute;
    top: -15px;
    right: 20px;
    background-color: var(--accent);
    color: var(--bg-primary);
    padding: 8px 16px;
    border-radius: 50px;
    font-weight: 700;
    font-size: 1rem;
}

.deal-card h3 {
    font-size: 1.4rem;
    margin-bottom: 12px;
    color: var(--text-primary);
}

.deal-card p {
    color: var(--text-secondary);
    margin-bottom: 20px;
    font-size: 0.95rem;
}

.deal-link {
    display: inline-block;
    color: var(--accent);
    font-weight: 600;
    padding-bottom: 4px;
    border-bottom: 2px solid transparent;
    transition: border-color 0.3s ease;
}

.deal-link:hover {
    border-bottom-color: var(--accent);
}

/* ============================
   Editorial Section
   ============================ */
.editorial-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: 30px;
}

@media (max-width: 1024px) {
    .editorial-grid {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 768px) {
    .editorial-grid {
        grid-template-columns: 1fr;
    }
}

.editorial-card {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 12px;
    overflow: hidden;
    transition: all 0.3s ease;
}

.editorial-card:hover {
    border-color: var(--accent);
    box-shadow: var(--shadow);
}

.featured-article {
    grid-row: span 2;
}

.editorial-image {
    width: 100%;
    height: 100%;
    min-height: 300px;
    overflow: hidden;
}

.featured-article .editorial-image {
    min-height: 500px;
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.05);
}

.editorial-text {
    padding: 24px;
}

.featured-article .editorial-text {
    padding: 32px;
}

.article-tag {
    display: inline-block;
    background-color: rgba(212, 175, 55, 0.1);
    color: var(--accent);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    padding: 6px 12px;
    border-radius: 50px;
    margin-bottom: 12px;
}

.editorial-card h3 {
    font-size: 1.2rem;
    margin-bottom: 12px;
    color: var(--text-primary);
    line-height: 1.4;
}

.featured-article h3 {
    font-size: 1.6rem;
}

.editorial-text p {
    font-size: 0.9rem;
    color: var(--text-secondary);
    margin-bottom: 16px;
    line-height: 1.6;
}

.read-more {
    display: inline-block;
    color: var(--accent);
    font-weight: 600;
    font-size: 0.9rem;
    transition: all 0.3s ease;
    padding-bottom: 4px;
    border-bottom: 2px solid transparent;
}

.read-more:hover {
    border-bottom-color: var(--accent);
}

/* ============================
   Newsletter Section
   ============================ */
.newsletter-section {
    background: linear-gradient(135deg, var(--bg-secondary) 0%, var(--bg-tertiary) 100%);
    padding: 80px 20px;
    border-top: 1px solid var(--border);
}

.newsletter-content {
    max-width: 600px;
    margin: 0 auto;
    text-align: center;
}

.newsletter-content h2 {
    font-size: 2.2rem;
    margin-bottom: 12px;
    font-weight: 700;
}

.newsletter-content p {
    color: var(--text-secondary);
    margin-bottom: 30px;
    font-size: 1.05rem;
}

.newsletter-form {
