    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 40px;
    margin-bottom: 40px;
}

.footer-col h4 {
    font-size: 1rem;
    margin-bottom: 16px;
    color: var(--text-primary);
    font-weight: 600;
}

.footer-col ul {
    list-style: none;
}

.footer-col ul li {
    margin-bottom: 10px;
}

.footer-col a {
    font-size: 0.9rem;
    color: var(--text-secondary);
    transition: color 0.3s ease;
}

.footer-col a:hover {
    color: var(--accent);
}

.footer-bottom {
    padding-top: 30px;
    border-top: 1px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 20px;
}

.footer-bottom p {
    font-size: 0.85rem;
    color: var(--text-secondary);
}

.footer-bottom ul {
    list-style: none;
    display: flex;
    gap: 30px;
}

.footer-bottom a {
    font-size: 0.85rem;
    color: var(--text-secondary);
}

/* ============================
   Responsive Design
   ============================ */
@media (max-width: 768px) {
    .header-content {
        flex-direction: column;
        gap: 20px;
    }

    .nav {
        flex-direction: column;
        gap: 20px;
        justify-content: center;
        text-align: center;
    }

    .hero-content h2 {
        font-size: 2.5rem;
    }

    .hero-content p {
        font-size: 1.1rem;
    }

    .section {
        padding: 60px 0;
    }

    .section-header h2 {
        font-size: 2rem;
    }

    .products-grid {
